@Service
@Transactional
public class OrderService {

    @Autowired
    private EntityManager entityManager;

    public void processOrderLifecycle(Long orderId) {
        // 1. Transient State
        Order newOrder = new Order();
        newOrder.setStatus("PENDING");

        // 2. Managed State (Persisted)
        entityManager.persist(newOrder);
        // At this point, newOrder has an ID and is tracked. 
        // Modifying newOrder.setStatus("PROCESSING") here will auto-update the DB on flush.

        // Transaction commits, context closes...
        // newOrder is now in the DETACHED state.

        // Simulating loading an existing entity (Managed State)
        Order managedOrder = entityManager.find(Order.class, orderId);

        // 4. Removed State
        if (managedOrder != null && "CANCELLED".equals(managedOrder.getStatus())) {
            entityManager.remove(managedOrder); 
            // Marked for deletion; DELETE SQL fires upon flush.
        }
    }
}
